    const bc=K.beard==='white'?'#ecebe6':K.hair;
    if(K.beard==='long') s+=`<path d="M51 50 Q52 72 60 74 Q68 72 69 50 Q66 58 60 58 Q54 58 51 50Z" fill="${bc}"/><path d="M55 53 Q60 51 65 53 Q60 55 55 53Z" fill="${bc}"/>`;
    if(K.beard==='white') s+=`<path d="M49 46 Q48 76 60 80 Q72 76 71 46 Q66 58 60 58 Q54 58 49 46Z" fill="${bc}"/><path d="M54 53 Q60 50 66 53 Q60 56 54 53Z" fill="${bc}"/>`;
