    if(K.beard==='mus') s+=`<path d="M54 54 Q57 52 60 53.5 Q63 52 66 54 Q66 57 64 59 M54 54 Q54 57 56 59" stroke="${bc}" stroke-width="1.2" fill="none"/>`;
